import os

import numpy as np

from mudlab.generic.io.utils import get_case_insensitive_glob
from mudlab.generic.utils import u

from ..base_parser import BaseParser
from .namespace import xrd_parsers
from .xrd_parser_mixin import XRDParserMixin


@xrd_parsers.register_parser()
class UXDParser(XRDParserMixin, BaseParser):
    """
        ASCII Bruker/Siemens DIFFRAC *.UXD format parser.

        The header is a block of ';' comment lines and `_KEYWORD=value` lines,
        terminated by a data marker:
          * `_2THETACOUNTS` / `_2THETACPS` — rows of "2theta  value"
          * `_COUNTS` / `_CPS`            — single-column values; 2theta is
                                            reconstructed from _START/_STEPSIZE
        Counts are normalised to counts-per-second using `_STEPTIME`
        (consistent with the CPI, XRDML and RAW parsers). Only the first data
        range is read.
    """

    description = "Bruker/Siemens *.UXD"
    extensions = get_case_insensitive_glob("*.UXD")

    @classmethod
    def _parse_header(cls, filename, fp, data_objects=None, close=False):
        f = fp

        try:
            basename = u(os.path.basename(filename))
        except Exception:
            basename = None

        data_objects = cls._adapt_data_object_list(data_objects, num_samples=1)

        f.seek(0)
        meta = {}
        data_start = None
        paired = False
        already_cps = False
        while True:
            line = f.readline()
            if line == "":            # EOF without a data marker
                data_start = f.tell()
                break
            s = line.strip()
            if not s or s.startswith(";"):
                continue
            up = s.upper()
            if up.startswith("_2THETACOUNTS") or up.startswith("_2THETACPS"):
                paired = True
                already_cps = "CPS" in up
                data_start = f.tell()
                break
            if up.startswith("_COUNTS") or up.startswith("_CPS"):
                paired = False
                already_cps = "CPS" in up
                data_start = f.tell()
                break
            if s.startswith("_") and "=" in s:
                key, _, val = s[1:].partition("=")
                meta[key.strip().upper()] = val.strip().strip("'").strip('"')

        def fnum(key, default=None):
            try:
                return float(meta[key])
            except (KeyError, ValueError, TypeError):
                return default

        steptime = fnum("STEPTIME", 1.0) or 1.0
        wl1 = fnum("WL1")
        wl2 = fnum("WL2")
        ratio = fnum("WLRATIO", 0.5)

        # UXD wavelengths are in Angstrom; MudLab goniometers use nm (÷10).
        def nm(v):
            return (v / 10.0) if v else None
        if wl1 and wl2 and ratio is not None:
            alpha_average = (wl1 + ratio * wl2) / (1.0 + ratio) / 10.0
        else:
            alpha_average = nm(wl1)

        data_objects[0].update(
            filename=basename,
            name=meta.get("SAMPLE", ""),
            target_type=meta.get("ANODE", ""),
            alpha1=nm(wl1),
            alpha2=nm(wl2),
            alpha_factor=ratio,
            alpha_average=alpha_average,
            count_time=(1.0 if already_cps else steptime),
            twotheta_min=fnum("START"),
            twotheta_step=fnum("STEPSIZE"),
            radius=fnum("GONIOMETER_RADIUS"),
            divergence=fnum("DIVERGENCE"),
            data_start=data_start,
        )
        # Remember the data layout for _parse_data:
        data_objects[0]._uxd_paired = paired

        if close: f.close()
        return data_objects

    @classmethod
    def _parse_data(cls, filename, fp, data_objects=None, close=False):
        f = fp
        obj = data_objects[0]
        if obj.data is None:
            obj.data = []

        count_time = getattr(obj, "count_time", 1.0) or 1.0
        paired = getattr(obj, "_uxd_paired", True)
        start = obj.twotheta_min if obj.twotheta_min is not None else 0.0
        step = obj.twotheta_step if obj.twotheta_step is not None else 1.0

        if f is not None:
            f.seek(obj.data_start)
            n = 0
            while True:
                line = f.readline()
                if line == "":                       # EOF
                    break
                s = line.strip().replace(",", ".")
                if not s:
                    continue
                if s.startswith("_") or s.startswith(";"):
                    break                            # next range / keyword block
                parts = s.split()
                try:
                    if paired:
                        x = float(parts[0])
                        y = float(parts[1])
                    else:
                        x = start + step * n
                        y = float(parts[0])
                except (IndexError, ValueError):
                    continue
                obj.data.append([x, y / count_time])
                n += 1

        obj.data = np.array(obj.data)

        # Fill in the x-range from the actual data (needed for the goniometer).
        if len(obj.data):
            obj.twotheta_min = float(obj.data[0, 0])
            obj.twotheta_max = float(obj.data[-1, 0])
            obj.twotheta_count = int(obj.data.shape[0])

        if close: f.close()
        return data_objects

    pass # end of class
